            elif w0 is None and w12 is None and w4 is not None and w8 is not None and w4 == w8:
                row = [9, w4, 9]
            # Case E3: [7,7,7,7] pattern - all same
            elif w0 is not None and w4 is not None and w8 is not None and w12 is not None and w0 == w4 == w8 == w12:
